sited.script:

    // 動態解析「標籤頁」的函式
    function tags_parse(url, html) {
        var $ = cheerio.load(html);
        var list = [];
        // 遍歷 ID 為 nav 的主導覽列下的每一個分組
        $('li.has-child').each(function() {
            var $$ = cheerio.load($(this).html());
			var groupElement = $(this);
            var groupName = $$('a').first().text().trim();
            // 在該分組下，尋找所有子項目連結
            $$('ul li a').each(function() {
                var itemElement = $$(this);
                var itemTitle = itemElement.text().trim();
                var itemUrl = itemElement.attr('href');
                if (itemUrl && itemTitle) {
                    list.push({
                        group: gbk2big5.traditionalized(groupName),
                        title: gbk2big5.traditionalized(itemTitle),
                        url: "https://123av.com/zh/"+itemUrl+"?page=@page"
                    });
                }
            });
        });
        return JSON.stringify(list);
    }

    function home_list_parse(url, html){
        var $ = cheerio.load(html);
        var list = [];

        $('section').each(function(){
            var $$ = cheerio.load($(this).html());
            var group_name = gbk2big5.traditionalized($$("h2").text().trim());
            $$('div.box-item').each(function() {
                var $$$ = cheerio.load($(this).html());
                if ($$$("div.detail a").attr('href')) list.push({group: group_name,url:"https://123av.com/zh/"+$$$("div.detail a").attr('href'), name:gbk2big5.traditionalized($$$("div.detail a").text()), logo:$$$("img").attr('data-src')});
            });
        });


        return JSON.stringify(list);
    }

    // 核心的「內容列表」解析函式
    function list_parse(url, html){
        var $ = cheerio.load(html);
        var list = [];

        $('section div.box-item').each(function() {
            var $$ = cheerio.load($(this).html());
            if ($$("div.detail a").attr('href')) list.push({url:"https://123av.com/zh/"+$$("div.detail a").attr('href'), name:gbk2big5.traditionalized($$("div.detail a").text()), logo:$$("img").attr('data-src')})
        });

        return JSON.stringify(list);
    }

    // 影片播放來源的解析函式
    function book_parse_api_response(url, html) {
        var $ = cheerio.load(html);
        var book = {
            name: gbk2big5.traditionalized($("h1").text().trim()),
            logo: $("#player").attr("data-poster"),
            sections: [{name: "播放", url: url}]
        };
        return JSON.stringify(book);
    }

    function section_parse(url, html) {
        return JSON.stringify({type:"webview_player", data: url});
    }

